const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then } = require('@cucumber/cucumber');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function todoItems() {
  return Array.from(this.document.querySelectorAll('.todo-list li'));
}

function nthTodo(n) {
  return todoItems.call(this)[n];
}

function inputEl() {
  return this.document.querySelector('.new-todo');
}

function mainSection() {
  return this.document.querySelector('.main');
}

function footerSection() {
  return this.document.querySelector('.footer');
}

function toggleAllCheckbox() {
  return this.document.querySelector('.toggle-all');
}

function clearCompletedButton() {
  return this.document.querySelector('.clear-completed');
}

function counterSpan() {
  return this.document.querySelector('.todo-count');
}

function editInput(li) {
  return li.querySelector('.edit');
}

function todoLabel(li) {
  return li.querySelector('.view label');
}

function todoToggle(li) {
  return li.querySelector('.view .toggle');
}

function filterLink(name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === name) return a;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app has no todos', function () {
  // world.js already loaded a fresh app; nothing to seed.
});

Given('the user has created a todo {string}', function (title) {
  const input = inputEl.call(this);
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true,
  }));
});

Given('the user has created a completed todo {string}', function (title) {
  // Create the todo first.
  const input = inputEl.call(this);
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true,
  }));
  // Re-query after render, then toggle the LAST item (the one just created).
  const items = todoItems.call(this);
  const li = items[items.length - 1];
  if (li) {
    const checkbox = todoToggle.call(this, li);
    if (checkbox && !checkbox.checked) {
      checkbox.click();
    }
  }
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When('the user types {string} in the new todo input', function (text) {
  const input = inputEl.call(this);
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user presses Enter', function () {
  const input = inputEl.call(this);
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true,
  }));
});

When('the user toggles the first todo', function () {
  const li = todoItems.call(this)[0];
  if (li) todoToggle.call(this, li).click();
});

When('the user clicks the toggle-all checkbox', function () {
  toggleAllCheckbox.call(this).click();
});

When('the user double-clicks the first todo label', function () {
  const li = todoItems.call(this)[0];
  if (li) {
    const label = todoLabel.call(this, li);
    const evt = new this.window.MouseEvent('dblclick', { bubbles: true });
    label.dispatchEvent(evt);
  }
});

When('the user types {string} in the edit input', function (text) {
  const li = todoItems.call(this)[0];
  if (li) {
    const ei = editInput.call(this, li);
    ei.value = text;
    ei.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }
});

When('the user presses Enter in the edit input', function () {
  const li = todoItems.call(this)[0];
  if (li) {
    const ei = editInput.call(this, li);
    ei.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true,
    }));
  }
});

When('the user presses Escape in the edit input', function () {
  const li = todoItems.call(this)[0];
  if (li) {
    const ei = editInput.call(this, li);
    ei.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true,
    }));
  }
});

When('the user blurs the edit input', function () {
  const li = todoItems.call(this)[0];
  if (li) {
    const ei = editInput.call(this, li);
    ei.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }
});

When('the user clears the edit input', function () {
  const li = todoItems.call(this)[0];
  if (li) {
    const ei = editInput.call(this, li);
    ei.value = '';
    ei.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }
});

When('the user clicks the clear-completed button', function () {
  clearCompletedButton.call(this).click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the page is reloaded', function () {
  // Dispose the current app, re-seed localStorage (already persisted), and reload.
  const stored = this.window.localStorage.getItem('todos-todomvc');
  this.disposeApp();
  this.loadApp();
  // Restore localStorage so the reloaded app can read persisted todos.
  if (stored !== null) {
    this.window.localStorage.setItem('todos-todomvc', stored);
  }
  // Re-run init after loadApp so the app reads the seeded storage.
  const appSource = require('node:fs').readFileSync(
    require('node:path').join(__dirname, '..', '..', 'js', 'app.js'), 'utf8',
  );
  this.window.eval(appSource);
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('the main section should be hidden', function () {
  const ms = mainSection.call(this);
  if (!ms) return;
  const style = this.window.getComputedStyle(ms);
  if (style.display !== 'none') {
    throw new Error(`Expected main section to be hidden, but display is "${style.display}"`);
  }
});

Then('the footer should be hidden', function () {
  const ft = footerSection.call(this);
  if (!ft) return;
  const style = this.window.getComputedStyle(ft);
  if (style.display !== 'none') {
    throw new Error(`Expected footer to be hidden, but display is "${style.display}"`);
  }
});

Then('the new todo input should be focused', function () {
  const input = inputEl.call(this);
  if (this.document.activeElement !== input) {
    throw new Error('Expected new todo input to be focused');
  }
});

Then('the todo list should contain {int} todo', function (count) {
  const items = todoItems.call(this);
  if (items.length !== count) {
    throw new Error(`Expected ${count} todo(s), found ${items.length}`);
  }
});

Then('the todo list should contain {int} todos', function (count) {
  const items = todoItems.call(this);
  if (items.length !== count) {
    throw new Error(`Expected ${count} todo(s), found ${items.length}`);
  }
});

Then('the first todo should have title {string}', function (title) {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  const label = todoLabel.call(this, li);
  if (label.textContent.trim() !== title) {
    throw new Error(`Expected title "${title}", found "${label.textContent.trim()}"`);
  }
});

Then('the first todo should not be completed', function () {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  if (li.classList.contains('completed')) {
    throw new Error('Expected first todo to NOT be completed');
  }
});

Then('the first todo should be completed', function () {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  if (!li.classList.contains('completed')) {
    throw new Error('Expected first todo to be completed');
  }
});

Then('the new todo input should be empty', function () {
  const input = inputEl.call(this);
  if (input.value !== '') {
    throw new Error(`Expected new todo input to be empty, found "${input.value}"`);
  }
});

Then('all todos should be completed', function () {
  const items = todoItems.call(this);
  for (const li of items) {
    if (!li.classList.contains('completed')) {
      throw new Error('Expected all todos to be completed');
    }
  }
});

Then('the toggle-all checkbox should be checked', function () {
  const cb = toggleAllCheckbox.call(this);
  if (!cb.checked) {
    throw new Error('Expected toggle-all checkbox to be checked');
  }
});

Then('the first todo should be in editing mode', function () {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  if (!li.classList.contains('editing')) {
    throw new Error('Expected first todo to be in editing mode');
  }
});

Then('the edit input should contain {string}', function (text) {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  const ei = editInput.call(this, li);
  if (ei.value !== text) {
    throw new Error(`Expected edit input to contain "${text}", found "${ei.value}"`);
  }
});

Then('the edit input should be focused', function () {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  const ei = editInput.call(this, li);
  if (this.document.activeElement !== ei) {
    throw new Error('Expected edit input to be focused');
  }
});

Then('the first todo should not be in editing mode', function () {
  const li = nthTodo.call(this, 0);
  if (!li) throw new Error('No todo items found');
  if (li.classList.contains('editing')) {
    throw new Error('Expected first todo to NOT be in editing mode');
  }
});

Then('the counter should display {string}', function (text) {
  const cs = counterSpan.call(this);
  if (!cs) throw new Error('Counter element not found');
  const actual = cs.textContent.trim();
  if (actual !== text) {
    throw new Error(`Expected counter "${text}", found "${actual}"`);
  }
});

Then('the clear-completed button should be hidden', function () {
  const btn = clearCompletedButton.call(this);
  if (!btn) return;
  const style = this.window.getComputedStyle(btn);
  if (style.display !== 'none') {
    throw new Error('Expected clear-completed button to be hidden');
  }
});

Then('the second todo should have title {string}', function (title) {
  const li = nthTodo.call(this, 1);
  if (!li) throw new Error('Second todo not found');
  const label = todoLabel.call(this, li);
  if (label.textContent.trim() !== title) {
    throw new Error(`Expected title "${title}", found "${label.textContent.trim()}"`);
  }
});

Then('the second todo should be completed', function () {
  const li = nthTodo.call(this, 1);
  if (!li) throw new Error('Second todo not found');
  if (!li.classList.contains('completed')) {
    throw new Error('Expected second todo to be completed');
  }
});

Then('the {string} filter link should be selected', function (name) {
  const a = filterLink.call(this, name);
  if (!a) throw new Error(`Filter link "${name}" not found`);
  if (!a.classList.contains('selected')) {
    throw new Error(`Expected "${name}" filter link to be selected`);
  }
});

Then('the {string} filter link should not be selected', function (name) {
  const a = filterLink.call(this, name);
  if (!a) throw new Error(`Filter link "${name}" not found`);
  if (a.classList.contains('selected')) {
    throw new Error(`Expected "${name}" filter link to NOT be selected`);
  }
});

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-todomvc';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var nextId = 1;
  var editingId = null;
  var currentFilter = '/';

  // ---- DOM helpers ----

  function $(sel) { return document.querySelector(sel); }
  function $$(sel) { return document.querySelectorAll(sel); }

  function todoListEl() { return $('.todo-list'); }
  function mainEl() { return $('.main'); }
  function footerEl() { return $('.footer'); }
  function newTodoEl() { return $('.new-todo'); }
  function toggleAllEl() { return $('.toggle-all'); }
  function clearCompletedEl() { return $('.clear-completed'); }
  function counterEl() { return $('.todo-count'); }

  // ---- Storage ----

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        todos = JSON.parse(raw);
        if (todos.length) {
          nextId = Math.max.apply(null, todos.map(function (t) { return t.id; })) + 1;
        }
      }
    } catch (e) {
      todos = [];
    }
  }

  // ---- Todo CRUD ----

  /** @planks("the user has created a todo {string}") */
  function addTodo(title) {
    title = title.trim();
    if (!title) return null;
    var todo = { id: nextId++, title: title, completed: false };
    todos.push(todo);
    save();
    return todo;
  }

  /** @planks("the user clears the edit input") */
  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
  }

  /** @planks("the user toggles the first todo") */
  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
  }

  /** @planks("the user clicks the toggle-all checkbox") */
  function toggleAll() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    save();
  }

  /** @planks("the user presses Enter in the edit input") */
  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      removeTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = newTitle;
        break;
      }
    }
    save();
  }

  /** @planks("the user clicks the clear-completed button") */
  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
  }

  // ---- Filter ----

  function filteredTodos() {
    if (currentFilter === '/active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentFilter === '/completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos.slice();
  }

  function readFilter() {
    var hash = location.hash || '#/';
    currentFilter = hash.replace(/^#/, '') || '/';
  }

  // ---- Rendering ----

  /**
   * @planks("the main section should be hidden")
   * @planks("the footer should be hidden")
   * @planks("the counter should display {string}")
   * @planks("the toggle-all checkbox should be checked")
   * @planks("the clear-completed button should be hidden")
   * @planks("the {string} filter link should be selected")
   * @planks("the {string} filter link should not be selected")
   */
  function render() {
    var list = todoListEl();
    list.innerHTML = '';

    var items = filteredTodos();
    items.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      if (editingId === todo.id) li.classList.add('editing');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      list.appendChild(li);
    });

    // Visibility
    var hasTodos = todos.length > 0;
    mainEl().style.display = hasTodos ? '' : 'none';
    footerEl().style.display = hasTodos ? '' : 'none';

    // Counter
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var noun = activeCount === 1 ? 'item' : 'items';
    counterEl().innerHTML = '<strong>' + activeCount + '</strong> ' + noun + ' left';

    // Toggle-all
    var allDone = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAllEl().checked = allDone;

    // Clear-completed
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedEl().style.display = hasCompleted ? '' : 'none';

    // Filter links
    var links = $$('.filters a');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      var href = a.getAttribute('href').replace('#', '') || '/';
      if (href === currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // ---- Event wiring ----

  function bindEvents() {
    // New todo: Enter
    newTodoEl().addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        var val = newTodoEl().value.trim();
        if (val) {
          addTodo(newTodoEl().value);
          newTodoEl().value = '';
          render();
        }
      }
    });

    // List delegation: toggle, destroy, dblclick, edit keydown, blur
    todoListEl().addEventListener('click', function (e) {
      var target = e.target;
      var li = target.closest ? target.closest('li') : null;
      if (!li) return;
      var id = Number(li.dataset.id);

      if (target.classList.contains('toggle')) {
        e.preventDefault();
        // happy-dom .click() does not natively toggle checkbox; set state manually.
        target.checked = !target.checked;
        toggleTodo(id);
        render();
      } else if (target.classList.contains('destroy')) {
        removeTodo(id);
        render();
      }
    });

    todoListEl().addEventListener('dblclick', function (e) {
      var target = e.target;
      if (target.tagName !== 'LABEL') return;
      var li = target.closest ? target.closest('li') : null;
      if (!li) return;
      var id = Number(li.dataset.id);
      editingId = id;
      render();
      // Re-query after render since DOM was rebuilt.
      var newLi = todoListEl().querySelector('li[data-id="' + id + '"]');
      if (newLi) {
        var editInput = newLi.querySelector('.edit');
        if (editInput) editInput.focus();
      }
    });

    todoListEl().addEventListener('keydown', function (e) {
      var target = e.target;
      if (!target.classList.contains('edit')) return;
      var li = target.closest('li');
      if (!li) return;
      var id = Number(li.dataset.id);

      if (e.keyCode === ENTER_KEY) {
        editTodo(id, target.value);
        editingId = null;
        render();
      } else if (e.keyCode === ESCAPE_KEY) {
        editingId = null;
        render();
      }
    });

    todoListEl().addEventListener('blur', function (e) {
      var target = e.target;
      if (!target.classList.contains('edit')) return;
      var li = target.closest('li');
      if (!li) return;
      var id = Number(li.dataset.id);
      if (editingId === id) {
        editTodo(id, target.value);
        editingId = null;
        render();
      }
    }, true);

    // Toggle-all
    toggleAllEl().addEventListener('click', function () {
      toggleAll();
      render();
    });

    // Clear completed
    clearCompletedEl().addEventListener('click', function () {
      clearCompleted();
      render();
    });

    // Routing
    window.addEventListener('hashchange', function () {
      readFilter();
      render();
    });
